import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './UserProfilePage.css';

const UserProfilePage = ({ user: currentUser }) => {
  const { uniqueId } = useParams();
  const navigate = useNavigate();
  const [profileUser, setProfileUser] = useState(null);
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchUserProfile();
  }, [uniqueId]);

  const fetchUserProfile = async () => {
    try {
      setLoading(true);
      setError('');
      
      // Получаем информацию о пользователе (включая проекты)
      const userResponse = await axios.get(`/api/users/by-unique-id/${uniqueId}`);
      setProfileUser(userResponse.data);
      setProjects(userResponse.data.projects || []);
      
    } catch (error) {
      if (error.response?.status === 404) {
        setError('Пользователь не найден');
      } else {
        setError('Ошибка загрузки профиля');
      }
    } finally {
      setLoading(false);
    }
  };

  const isOwnProfile = currentUser && profileUser && currentUser.id === profileUser.id;

  if (loading) {
    return (
      <div className="profile-page">
        <div className="loading">Загрузка профиля...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="profile-page">
        <div className="profile-error">
          <h2>Ошибка</h2>
          <p>{error}</p>
          <button className="btn btn-primary" onClick={() => navigate('/')}>
            На главную
          </button>
        </div>
      </div>
    );
  }

  if (!profileUser) {
    return (
      <div className="profile-page">
        <div className="profile-error">
          <h2>Пользователь не найден</h2>
          <button className="btn btn-primary" onClick={() => navigate('/')}>
            На главную
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="profile-page">
      <div className="profile-container">
        <div className="profile-header">
          <div className="profile-avatar">
            {profileUser.avatar ? (
              <img src={profileUser.avatar} alt="Аватар" />
            ) : (
              <div className="default-avatar">
                {profileUser.nickname.charAt(0).toUpperCase()}
              </div>
            )}
          </div>
          
          <div className="profile-info">
            <h1>{profileUser.nickname}</h1>
            <p className="profile-id">ID: {profileUser.unique_id}</p>
            {profileUser.description && (
              <p className="profile-description">{profileUser.description}</p>
            )}
            <p className="profile-joined">
              На сайте с {new Date(profileUser.created_at).toLocaleDateString('ru-RU')}
            </p>
          </div>

          {isOwnProfile && (
            <div className="profile-actions">
              <button 
                className="btn btn-primary"
                onClick={() => navigate('/settings')}
              >
                Настройки
              </button>
            </div>
          )}
        </div>

        <div className="profile-content">
          <div className="projects-section">
            <h2>Проекты ({projects.length})</h2>
            
            {projects.length === 0 ? (
              <div className="no-projects">
                <p>У пользователя пока нет проектов</p>
              </div>
            ) : (
              <div className="projects-grid">
                {projects.map((project) => (
                  <div key={project.id} className="project-card">
                    <h3>{project.title}</h3>
                    {project.description && (
                      <p className="project-description">{project.description}</p>
                    )}
                    <div className="project-meta">
                      <small>
                        Создан {new Date(project.created_at).toLocaleDateString('ru-RU')}
                      </small>
                      {isOwnProfile && project.files && project.files.length > 0 && (
                        <small className="files-count">
                          Файлов: {project.files.length}
                        </small>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserProfilePage;
